```java
for (int h = 0; h <= 256; h++) { // 높이를 가능한 경우 모두 탐색
			int remove = 0;
			int place = 0;

			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (map[i][j] > h) {
						remove += map[i][j] - h; // 부셔야 되는 경우 횟수
					} else {
						place += h - map[i][j]; // 설치해야 되는 경우 횟수
					}
				}
			}

			if (remove + b >= place) { // 시간 계산
				int time = remove * 2 + place;
				if (time <= restime) {
					restime = time;
					resh = h;
				}
			}
		}
```

